code='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max({v: sum(row.count(v) for row in grid) for v in {x for row in grid for x in row}}, key=lambda v: sum(row.count(v) for row in grid))
    seen=set(); objs=[]
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color==bg or (r,c) in seen: continue
            q=[(r,c)]; seen.add((r,c)); cells=[]
            while q:
                y,x=q.pop(); cells.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                        seen.add((yy,xx)); q.append((yy,xx))
            if len(cells)>=2:
                objs.append((color,min(y for y,x in cells),max(y for y,x in cells),min(x for y,x in cells),max(x for y,x in cells)))
    out=[[bg]*w for _ in range(h)]
    for color,r0,r1,c0,c1 in objs:
        for r in range(r0,r1+1):
            for c in range(c0,c1+1): out[r][c]=color
    return out
'''
